computed_stats.meleeDamageMult:
double get meleeDamageMult {
    var m = 0.75;
    if (has('forte')) m += 0.30;
    if (has('robusto')) m += 0.15;
    if (has('fraco')) m -= 0.30;
    if (has('franzino')) m -= 0.15;
    m += 0.05 * level('armas_brancas') + 0.03 * level('forca');
    return m;
  }

computed_stats.capacityMult:
double get capacityMult {
    var m = 1.0;
    if (has('forte')) m += 0.2;
    if (has('fraco')) m -= 0.2;
    if (has('organizado')) m += 0.3;
    if (has('desorganizado')) m -= 0.3;
    return m;
  }

computed_stats.staminaMult:
double get staminaMult {
    var m = 1.0;
    if (has('atletico')) m += 0.4;
    if (has('em_forma')) m += 0.2;
    if (has('fora_de_forma')) m -= 0.2;
    if (has('sedentario')) m -= 0.4;
    m += 0.03 * level('folego');
    return m;
  }

computed_stats.noiseMult:
double get noiseMult {
    var m = 1.0;
    if (has('passos_leves')) m -= 0.3;
    if (has('desastrado')) m += 0.3;
    if (has('cacador')) m -= 0.15;
    m -= 0.04 * level('furtividade');
    return max(0.3, m);
  }

computed_stats.healTimeMult:
double get healTimeMult {
    var m = has('cura_rapida')
        ? 0.7
        : has('cura_lenta')
            ? 1.3
            : 1.0;
    m *= 1 - 0.05 * level('primeiros_socorros');
    return m;
  }

computed_stats.infectChance:
double infectChance(bool bite) {
    if (bite) {
      return has('imunidade_forte')
          ? 0.6
          : has('imunidade_fraca')
              ? 1.0
              : 0.85;
    }
    return has('imunidade_fraca') ? 0.15 : 0;
  }

build_rules.validate:
String? validateBuild(String professionId, Set<String> chosen) {
  final p = professionById[professionId];
  if (p == null) return 'Escolha uma profissão.';
  final all = {...p.freeTraits, ...chosen};
  for (final id in chosen) {
    final t = traitById[id];
    if (t == null) return 'Traço desconhecido.';
    if (p.freeTraits.contains(id)) return '${t.name} já vem da profissão.';
    for (final c in t.conflicts) {
      if (all.contains(c)) return '${t.name} conflita com ${traitById[c]!.name}.';
    }
  }
  if (pointsLeft(professionId, chosen) < 0) return 'Pontos insuficientes.';
  return null;
}

build_rules.points_left:
int pointsLeft(String professionId, Set<String> chosen) {
  final p = professionById[professionId];
  if (p == null) return 0;
  return p.points - chosen.fold(0, (s, id) => s + (traitById[id]?.cost ?? 0));
}
